const body = items[0].json.body || items[0].json;

let fileId = body.fileId || body.file_id;
let fileName = body.fileName || body.file_name;
let transcriptText = body.transcript || body.text || body.content;

if (!fileId && transcriptText) {
  return [{
    json: {
      fileId: null,
      fileName: fileName || 'Direct Input',
      content: transcriptText,
      mimeType: 'text/plain',
      source: 'direct'
    }
  }];
}

return [{
  json: {
    fileId: fileId,
    fileName: fileName,
    source: 'google-drive'
  }
}];

const fileData = items[0].json.file;
const binary = items[0].binary;

let textContent = '';

if (binary && binary.file) {
  const fileBuffer = Buffer.from(binary.file.data, 'base64');
  textContent = fileBuffer.toString('utf-8');
}

if (!textContent && items[0].json.content) {
  textContent = items[0].json.content;
}

return [{
  json: {
    fileId: fileData?.id || items[0].json.fileId,
    fileName: fileData?.name || items[0].json.fileName,
    content: textContent,
    mimeType: fileData?.mimeType || items[0].json.mimeType
  }
}];

const body = items[0].json.body || items[0].json;
const transcriptText = body.transcript || body.text || body.content;

return [{
  json: {
    fileId: null,
    fileName: body.fileName || 'Direct Input',
    content: transcriptText,
    mimeType: 'text/plain'
  }
}];

const input = items[0].json;

let response = input;

// Handle string response from AI
if (typeof input === 'string') {
  try {
    response = JSON.parse(input);
  } catch (e) {
    // Try to extract JSON from markdown code blocks
    const jsonMatch = input.match(/```json\s*([\s\S]*?)\s*```/) || input.match(/\{[\s\S]*\}/);
    if (jsonMatch) {
      try {
        response = JSON.parse(jsonMatch[1] || jsonMatch[0]);
      } catch (e2) {
        response = { features: [], actions: [], insights: [] };
      }
    } else {
      response = { features: [], actions: [], insights: [] };
    }
  }
}

// Handle nested response (some models wrap in "content" or "text")
if (response.content) {
  try {
    response = typeof response.content === 'string' ? JSON.parse(response.content) : response.content;
  } catch (e) {}
}
if (response.text) {
  try {
    response = typeof response.text === 'string' ? JSON.parse(response.text) : response.text;
  } catch (e) {}
}

const features = Array.isArray(response.features) ? response.features : [];
const actions = Array.isArray(response.actions) ? response.actions : [];
const insights = Array.isArray(response.insights) ? response.insights : [];

// Map features to Jira Story format
const featureItems = features.map(f => ({
  json: {
    itemType: 'feature',
    title: f.title || f.name || 'Untitled Feature',
    description: f.description || f.details || '',
    priority: f.priority || 'Medium',
    assignee: f.assignee || null
  }
}));

// Map actions to Jira Task format
const actionItems = actions.map(a => ({
  json: {
    itemType: 'action',
    title: a.title || a.name || 'Untitled Action',
    description: a.description || a.details || '',
    priority: a.priority || 'Medium',
    assignee: a.assignee || null
  }
}));

// Return combined items
return [...featureItems, ...actionItems];

const results = items.map(item => ({
  key: item.json.key || 'N/A',
  summary: item.json.summary || item.json.title || 'N/A',
  type: item.json.type || 'N/A'
}));

return [{
  json: {
    totalCreated: results.length,
    tickets: results,
    message: 'Created ' + results.length + ' Jira tickets from meeting transcript'
  }
}];
